package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="medical_records") public class MedicalRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="patient_id",nullable=false) private User patient; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="doctor_id",nullable=false) private DoctorProfile doctor; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="appointment_id") private Appointment appointment; @Column(length=255) private String diagnosis; @Column(columnDefinition="TEXT") private String notes; @Column(name="document_url",length=500) private String documentUrl; private LocalDateTime createdAt; @PrePersist void onCreate(){createdAt=LocalDateTime.now();} public MedicalRecord(){} public MedicalRecord(User p,DoctorProfile d,Appointment a,String diag,String n,String u){patient=p;doctor=d;appointment=a;diagnosis=diag;notes=n;documentUrl=u;} public Long getId(){return id;} public User getPatient(){return patient;} public DoctorProfile getDoctor(){return doctor;} public Appointment getAppointment(){return appointment;} public String getDiagnosis(){return diagnosis;} public String getNotes(){return notes;} public String getDocumentUrl(){return documentUrl;} public LocalDateTime getCreatedAt(){return createdAt;} }